@startuml

class Product {
  + name : string
  + description : string
  + netPrice : float
}

class Manufacturer {
  + name : string
}

class Country {
  + name : string
  + vatRate : float
  + currency : string
  + conversionRateToEuro : float
}

class Representative {
  + firstName : string
  + lastName : string
  + socialSecurityNumber : string
  + telephoneNumber : string
  + emailAddress : string
}

class Customer {
  + name : string
  + address : string
  + telephoneNumber : string
  + emailAddress : string
}

class Order {
  + orderID : string
  + quantity : int
  + orderDate : date
  + desiredDeliveryDate : date
}

Manufacturer "1" -- "*" Product : manufactures
Product "*" -- "1" Country : manufacturedIn
Product "*" -- "*" Country : availableIn
Representative "1" -- "1" Country : responsibleFor
Representative "1" -- "*" Order : places
Customer "1" -- "*" Order : places
Customer "*" -- "*" Country : resellsIn

@enduml

